DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _u AS SELECT s.id, s.supplier_id, s.doc_type, s.po_text, s.job_name, s.invoice_date, x.po_id, EXISTS (SELECT 1 FROM supplier_doc_pages p WHERE p.supplier_invoice_id = s.id) AS scanned FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x LEFT JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE1 %', (SELECT jsonb_build_object('cr', count(*) FILTER (WHERE doc_type='credit'), 'po_nojob', count(*) FILTER (WHERE po_id IS NOT NULL), 'txt_nomatch', count(*) FILTER (WHERE po_id IS NULL AND btrim(coalesce(po_text,''))<>''), 'notxt', count(*) FILTER (WHERE po_id IS NULL AND btrim(coalesce(po_text,''))=''), 'scan', count(*) FILTER (WHERE scanned), 'jn', count(*) FILTER (WHERE btrim(coalesce(job_name,''))<>''))::text FROM _u); END $$;
